CREATE OR REPLACE FUNCTION public.audit_report_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN SELECT business_id INTO bid FROM public.reviews WHERE id=NEW.review_id; INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,before_data,after_data) VALUES(bid,NEW.id,auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'review_report_submitted' ELSE 'review_report_activity' END,'Review report lifecycle recorded',CASE WHEN TG_OP='UPDATE' THEN jsonb_build_object('status',OLD.status) ELSE NULL END,jsonb_build_object('status',NEW.status,'reason_type',NEW.reason,'appeal_present',NEW.appeal<>'')); RETURN NEW; END; $$;
CREATE TRIGGER audit_report_changes AFTER INSERT OR UPDATE ON public.review_reports FOR EACH ROW EXECUTE FUNCTION public.audit_report_activity();
CREATE OR REPLACE FUNCTION public.audit_claim_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status OR NEW.evidence IS DISTINCT FROM OLD.evidence THEN INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,before_data,after_data) VALUES(NEW.business_id,NEW.id,auth.uid(),'claim_activity',CASE WHEN NEW.status IS DISTINCT FROM OLD.status THEN NEW.reason ELSE 'Private evidence updated' END,jsonb_build_object('status',OLD.status,'evidence_count',cardinality(OLD.evidence)),jsonb_build_object('status',NEW.status,'evidence_count',cardinality(NEW.evidence))); END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_claim_changes AFTER UPDATE ON public.business_claims FOR EACH ROW EXECUTE FUNCTION public.audit_claim_activity();